"""Helper function to calculate the distance between node a and b."""
def calculate_distance(a: Any, b: Any) -> object {
    (x1, y1) = a;
    (x2, y2) = b;
    return ((((x1 - x2) ** 2) + ((y1 - y2) ** 2)) ** 0.5);
}

"""compute the 2's complement of int value val"""
def _twos_complement(val: Any, bits: Any) -> object {
    if ((val & (1 << (bits - 1))) != 0) {
        val = val - (1 << bits);
    }
    return val;
}
